export const DEFAULT_OUTLINE_OPML = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<opml version=\"2.0\">\n  <head>\n    <title>Getting Started</title>\n    <dateModified>Tue, 10 Nov 2026 11:22:01 GMT</dateModified>\n    <expansionState>1,29</expansionState>\n  </head>\n  <body>\n    <outline text=\"How to use this outliner\">\n      <outline text=\"Click any line to edit. Press Enter for a new line, then Tab to indent — this is a nested outline, not a flat document.\"/>\n      <outline text=\"Click ▸ or ▾ beside a parent to show or hide its children\">\n        <outline text=\"⌘→ / ⌘← will do the same\"/>\n        <outline text=\"⌘⌥→ expands this heading’s subheads completely\"/>\n        <outline text=\"⌘⌥← collapses this heading’s subheads completely\"/>\n        <outline text=\"View → Expand All / Collapse All affects the whole outline\"/>\n      </outline>\n      <outline text=\"Keyboard\">\n        <outline text=\"On Windows or Linux, use Ctrl wherever you see ⌘\"/>\n        <outline text=\"Enter — new line below (same level, or first child if this line has subheads)\"/>\n        <outline text=\"Tab — indent under the line above; Shift+Tab — outdent\"/>\n        <outline text=\"Backspace at the start of a line — merge with the line above\"/>\n        <outline text=\"↑ / ↓ — Move to the previous or next line; ⌥↑ / ⌥↓ — at the same level\"/>\n        <outline text=\"Promote (⌘[) — lift this line’s children up beside it\"/>\n        <outline text=\"Demote (⌘]) — nest the following same-level lines under this one\"/>\n      </outline>\n      <outline text=\"Edit the title above the outline to rename the document\"/>\n      <outline text=\"Open and Save\">\n        <outline text=\"File → Open… / Save — OPML on your computer (re-saves in place when the browser supports it)\"/>\n        <outline text=\"Cloud → Open… / Save / Save As… / Delete… — Open from or save to Google Drive after Sign in with Google\"/>\n        <outline text=\"Cloud → Copy read-only / editable link — distinct share URLs (not interchangeable)\"/>\n      </outline>\n      <outline text=\"Edit → Find… / Replace… searches the outline\"/>\n      <outline text=\"Edit → Clear Outline empties the document\"/>\n      <outline text=\"View → Focus narrows the display to one branch; Unfocus shows everything again\"/>\n      <outline text=\"Features for bridge players\">\n        <outline text=\"!c !d !h !s — insert ♣ ♦ ♥ ♠\"/>\n        <outline text=\"PBN deals stay as text while you edit; View → Render PBN opens a read-only tab with compass diagrams (e.g. N:73.QJT.AQ54.T752 …, including mid-line)\"/>\n      </outline>\n      <outline text=\"Replace these tips with your own outline whenever you’re ready.\"/>\n      <outline text=\"There’s no charge for using the app — it’s free as in beer.\"/>\n      <outline text=\"If you have questions or suggestions, please post to the discussion forum:\">\n        <outline text=\"https://groups.google.com/g/tameware-outliner\"/>\n        <outline text=\"To join or to see messages, you must be signed in with a Google account.\"/>\n      </outline>\n    </outline>\n  </body>\n</opml>\n";
